import React, { useEffect, useMemo, useState } from "react";
import {
  Card,
  Space,
  Button,
  Upload,
  Typography,
  Table,
  Row,
  Col,
  Spin,
} from "antd";
import type { UploadProps } from "antd";
import { DownloadOutlined, InboxOutlined } from "@ant-design/icons";
import ReactECharts from "echarts-for-react";
import type { EChartsOption } from "echarts";
import mammoth from "mammoth";
import { marked } from "marked";
import DOMPurify from "dompurify";

const { Title, Text } = Typography;

const TEMPLATE_CONFIG = {
  md: {
    label: "Markdown 模板",
    fileName: "task-data-template.md",
    href: "/template.docx/task-data-template.md",
  },
  word: {
    label: "Word 模板",
    fileName: "task-data-template.docx",
    href: "/template.docx/task-data-template.docx",
  },
};

type TaskContentRow = {
  priority: string;
  count: number;
  taskContent: string;
};

function parseMd(text: string): TaskContentRow[] {
  const rows: TaskContentRow[] = [];
  const regex = /- ([^:]+):\s*(\d+)\s*\|\s*任务内容:\s*(.+)/g;
  let match: RegExpExecArray | null;
  while ((match = regex.exec(text)) !== null) {
    const priority = match[1]?.trim() ?? "";
    const count = Number(match[2]);
    const taskContent = (match[3] ?? "").trim();
    if (!priority || Number.isNaN(count) || !taskContent) continue;
    rows.push({ priority, count, taskContent });
  }
  return rows;
}

function parseWordText(text: string): TaskContentRow[] {
  const rows: TaskContentRow[] = [];
  const regex = /优先级:([^,]+),数量:(\d+),任务内容:([^;]+)/g;
  let match: RegExpExecArray | null;
  while ((match = regex.exec(text)) !== null) {
    const priority = match[1]?.trim() ?? "";
    const count = Number(match[2]);
    const taskContent = (match[3] ?? "").trim();
    if (!priority || Number.isNaN(count) || !taskContent) continue;
    rows.push({ priority, count, taskContent });
  }
  return rows;
}

async function readFileAsText(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(String(reader.result ?? ""));
    reader.onerror = () => reject(reader.error ?? new Error("读取文件失败"));
    reader.readAsText(file);
  });
}

async function readFileAsArrayBuffer(file: File): Promise<ArrayBuffer> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result as ArrayBuffer);
    reader.onerror = () => reject(reader.error ?? new Error("读取文件失败"));
    reader.readAsArrayBuffer(file);
  });
}

const EfficiencyAnalysisUploader: React.FC = () => {
  const [mdTemplate, setMdTemplate] = useState<string>("");
  const [mdTemplateHtml, setMdTemplateHtml] = useState<string>("");
  const [taskContentList, setTaskContentList] = useState<TaskContentRow[]>([]);
  const [parsing, setParsing] = useState(false);

  useEffect(() => {
    const load = async () => {
      try {
        const res = await fetch(TEMPLATE_CONFIG.md.href);
        const text = await res.text();
        setMdTemplate(text);
        const html = DOMPurify.sanitize(marked.parse(text) as string);
        setMdTemplateHtml(html);
      } catch {
        setMdTemplate("");
        setMdTemplateHtml("");
      }
    };
    load();
  }, []);

  const chartOption: EChartsOption | null = useMemo(() => {
    if (!taskContentList.length) return null;
    const categories = taskContentList.map((i) => i.priority);
    const values = taskContentList.map((i) => ({
      value: i.count,
      extra: { taskContent: i.taskContent },
    }));

    return {
      title: { text: "任务优先级分布" },
      tooltip: {
        trigger: "axis",
        formatter: (params: any) => {
          const first = Array.isArray(params) ? params[0] : params;
          const priority = first?.axisValue ?? "";
          const value = first?.data?.value ?? first?.value ?? "";
          const extra = first?.data?.extra?.taskContent;
          const rows = [
            `${priority}: ${value}`,
            extra ? `任务内容: ${extra}` : "",
          ].filter(Boolean);
          return rows.join("<br/>");
        },
      },
      xAxis: { type: "category", data: categories },
      yAxis: { type: "value" },
      series: [{ type: "bar", data: values }],
    };
  }, [taskContentList]);

  const beforeUpload: UploadProps["beforeUpload"] = async (file) => {
    setParsing(true);
    setTaskContentList([]);
    try {
      const lower = file.name.toLowerCase();
      let rows: TaskContentRow[] = [];

      if (lower.endsWith(".md")) {
        const text = await readFileAsText(file);
        rows = parseMd(text);
      } else if (lower.endsWith(".docx")) {
        const arrayBuffer = await readFileAsArrayBuffer(file);
        try {
          const res = await mammoth.extractRawText({ arrayBuffer });
          rows = parseWordText(res.value ?? "");
        } catch {
          const fallbackText = new TextDecoder("utf-8").decode(arrayBuffer);
          rows = parseWordText(fallbackText);
        }
      }

      setTaskContentList(rows);
    } finally {
      setParsing(false);
    }
    return false;
  };

  const columns = [
    { title: "优先级", dataIndex: "priority", key: "priority", width: 120 },
    { title: "任务数量", dataIndex: "count", key: "count", width: 120 },
    { title: "任务内容", dataIndex: "taskContent", key: "taskContent" },
  ];

  return (
    <div>
      <Title level={4} style={{ marginTop: 0 }}>
        上传解析与可视化
      </Title>

      <Row gutter={16}>
        <Col span={12}>
          <Card
            title="模板展示与下载"
            extra={
              <Space>
                <Button
                  icon={<DownloadOutlined />}
                  href={TEMPLATE_CONFIG.md.href}
                  download={TEMPLATE_CONFIG.md.fileName}
                >
                  下载 MD
                </Button>
                <Button
                  icon={<DownloadOutlined />}
                  href={TEMPLATE_CONFIG.word.href}
                  download={TEMPLATE_CONFIG.word.fileName}
                >
                  下载 Word
                </Button>
              </Space>
            }
          >
            <Space direction="vertical" style={{ width: "100%" }} size={12}>
              <div>
                <Text type="secondary">{TEMPLATE_CONFIG.md.label}</Text>
                {mdTemplateHtml ? (
                  <div
                    style={{
                      marginTop: 8,
                      padding: 12,
                      background: "#fafafa",
                      borderRadius: 8,
                    }}
                    dangerouslySetInnerHTML={{ __html: mdTemplateHtml }}
                  />
                ) : (
                  <pre
                    style={{
                      marginTop: 8,
                      padding: 12,
                      background: "#fafafa",
                      borderRadius: 8,
                    }}
                  >
                    {mdTemplate || "未找到模板文件"}
                  </pre>
                )}
              </div>
              <div>
                <Text type="secondary">{TEMPLATE_CONFIG.word.label}</Text>
                <pre
                  style={{
                    marginTop: 8,
                    padding: 12,
                    background: "#fafafa",
                    borderRadius: 8,
                  }}
                >
                  优先级:高,数量:15,任务内容:需求评审、接口开发、联调测试;
                  {"\n"}
                  优先级:中,数量:20,任务内容:UI适配、单元测试、文档编写;
                  {"\n"}
                  优先级:低,数量:8,任务内容:代码优化、日志整理、环境维护;
                </pre>
              </div>
            </Space>
          </Card>
        </Col>

        <Col span={12}>
          <Card title="多格式文件上传解析">
            <Upload.Dragger
              accept=".md,.docx"
              multiple={false}
              beforeUpload={beforeUpload}
              showUploadList={false}
              disabled={parsing}
            >
              <p className="ant-upload-drag-icon">
                <InboxOutlined />
              </p>
              <p className="ant-upload-text">点击或拖拽上传 .md / .docx</p>
              <p className="ant-upload-hint">
                解析完成后会自动生成图表与任务内容列表
              </p>
            </Upload.Dragger>

            <div style={{ marginTop: 16 }}>
              <Space>
                <Spin spinning={parsing} />
                <Text type="secondary">
                  {parsing ? "正在解析文件…" : "解析完成"}
                </Text>
              </Space>
            </div>
          </Card>
        </Col>
      </Row>

      <Row gutter={16} style={{ marginTop: 16 }}>
        <Col span={24}>
          <Card title="可视化">
            {chartOption ? (
              <ReactECharts option={chartOption} style={{ height: 320 }} />
            ) : (
              <Text type="secondary">上传文件后展示图表</Text>
            )}
          </Card>
        </Col>
      </Row>

      <Card title="任务内容列表" style={{ marginTop: 16 }}>
        <Table
          rowKey={(r) => `${r.priority}-${r.count}-${r.taskContent}`}
          columns={columns}
          dataSource={taskContentList}
          pagination={false}
          locale={{ emptyText: "上传文件后展示任务内容" }}
        />
      </Card>
    </div>
  );
};

export default EfficiencyAnalysisUploader;
